-- a889c971 | ما معنى الحديث الصحيح؟
UPDATE qa_questions SET
  answer = 'معناه أن يجتمع في الحديث خمسةُ أوصافٍ لا يسقط منها وصف: اتصالُ السند، وعدالةُ رواته، وتمامُ ضبطهم، والسلامةُ من الشذوذ، والسلامةُ من العلّة. وحدُّه عند ابن الصلاح: «الْحَدِيثُ الْمُسْنَدُ الَّذِي يَتَّصِلُ إِسْنَادُهُ» «بِنَقْلِ الْعَدْلِ الضَّابِطِ عَنِ الْعَدْلِ الضَّابِطِ إِلَى مُنْتَهَاهُ، وَلَا يَكُونُ شَاذًّا، وَلَا مُعَلَّلًا». وحدُّه عند ابن حجر: «وخبرُ الآحادِ بنقلِ عدلٍ تامِّ الضبطِ، متصلَ السند، غيرَ مُعَلَّل ولا شاذٍّ هو الصحيحُ لِذَاتِه»، وبينهما فروقٌ ثلاثة: أن ابن حجر جعل الجنس «خبرُ الآحادِ» فخرج به المتواتر، وزاد وصفَ الضبط قيدَ التمام «إشارةً إلى الرُّتبةِ العُليا في ذلك»، وقيَّده بقوله «لِذَاتِه» وهو قيدٌ «يُخرِجُ ما يسمى صحيحًا بأمرٍ خارجٍ عنه» أي الصحيح لغيره. والعدلُ «مَنْ له مَلَكَةٌ تَحْمِلُه على مُلازَمة التقوى والمروءة»، والضبطُ ضبطُ صدرٍ وضبطُ كتاب، والمعلَّلُ اصطلاحًا «ما فيه عِلَّةٌ خفيَّةٌ قادِحَةٌ»، والشاذُّ «ما يُخالِفُ فيه الراوي مَنْ هو أَرْجَحُ منه».',
  reference = 'مقدمة ابن الصلاح في علوم الحديث (معرفة أنواع علوم الحديث، ت نور الدين عتر، دار الفكر بسوريا ودار الفكر المعاصر ببيروت، ١٤٠٦هـ/١٩٨٦م): ص١١-١٢ (النوع الأول من أنواع علوم الحديث: معرفة الصحيح من الحديث)؛ نزهة النظر في توضيح نخبة الفكر لابن حجر (ت نور الدين عتر، مطبعة الصباح بدمشق، ط٣ ١٤٢١هـ/٢٠٠٠م): ص٥٨ (الصحيح لذاته وشرح تعريفه وبيان أقسام الضبط)، وص٥٩ (تفاوت رتب الصحيح) | الكلمات المفتاحية: حديث، صحيح، مصطلح',
  evidence = 'قال ابن الصلاح في النوع الأول من أنواع علوم الحديث: «أَمَّا الْحَدِيثُ الصَّحِيحُ: فَهُوَ الْحَدِيثُ الْمُسْنَدُ الَّذِي يَتَّصِلُ إِسْنَادُهُ» (ص١١) «بِنَقْلِ الْعَدْلِ الضَّابِطِ عَنِ الْعَدْلِ الضَّابِطِ إِلَى مُنْتَهَاهُ، وَلَا يَكُونُ شَاذًّا، وَلَا مُعَلَّلًا» (ص١٢) — بلفظ «عَنِ الْعَدْلِ الضَّابِطِ» لا ‹عن مثله›. واختصره ابن حجر في النخبة فقال: «وخبرُ الآحادِ بنقلِ عدلٍ تامِّ الضبطِ، متصلَ السند، غيرَ مُعَلَّل ولا شاذٍّ هو الصحيحُ لِذَاتِه» (ص٥٨)، وقال في شرحه: «قولُه: "وخبرُ الآحادِ" كالجِنْس، وباقي قُيودِه كالفَصْلِ» (ص٥٩). وفسَّر قيودَه فقال: «والمرادُ بالعَدْلِ: مَنْ له مَلَكَةٌ تَحْمِلُه على مُلازَمة التقوى والمروءة»، «والضَّبْطُ - ضبطُ صَدرٍ: وهو أن يُثبتَ ما سَمِعَه بحيثُ يتمكَّنُ من استحضارِهِ متى شاء» (ص٥٨)، «وضبطُ كتابٍ: وهو صِيانَتُه لَدَيْه منذُ سَمِعَ فيه وصحَّحَه إلى أنْ يُؤَدّيَ منه. وقُيِّد بالتامِّ إشارةً إلى الرُّتبةِ العُليا في ذلك. والمتصلُ: ما سَلِم إسنادُه مِنْ سُقوطٍ فيه بحيثُ يكونُ كلٌّ مِنْ رِجاله سمعَ ذلك المَرْوِيَّ من شيخه»، «والمُعَلَّلُ لغةً: ما فيه عِلَّةٌ، واصطلاحًا: ما فيه عِلَّةٌ خفيَّةٌ قادِحَةٌ. والشاذُّ لغةً: المُنفردُ، واصطلاحًا: ما يُخالِفُ فيه الراوي مَنْ هو أَرْجَحُ منه»، «وقوله: "لِذَاتِه" يُخرِجُ ما يسمى صحيحًا بأمرٍ خارجٍ عنه» (ص٥٩).',
  verification_status = 'verified'
WHERE id = 'a889c971-ce25-40cb-8838-5fbcd289a2d7'
  AND reference = 'مقدمة ابن الصلاح؛ نزهة النظر | الكلمات المفتاحية: حديث، صحيح، مصطلح'
  AND evidence = 'تعريف المحدثين للحديث الصحيح في كتب المصطلح.'
  AND answer = 'هو ما اتصل سنده بنقل العدل الضابط عن مثله إلى منتهاه من غير شذوذ ولا علة.';

-- 3c7c003b | ما تعريف الحديث الصحيح؟
UPDATE qa_questions SET
  answer = 'هو - بلفظ ابن الصلاح - «الْحَدِيثُ الْمُسْنَدُ الَّذِي يَتَّصِلُ إِسْنَادُهُ» «بِنَقْلِ الْعَدْلِ الضَّابِطِ عَنِ الْعَدْلِ الضَّابِطِ إِلَى مُنْتَهَاهُ، وَلَا يَكُونُ شَاذًّا، وَلَا مُعَلَّلًا». وبهذه الأوصاف «احْتِرَازٌ عَنِ الْمُرْسَلِ، وَالْمُنْقَطِعِ، وَالْمُعْضَلِ، وَالشَّاذِّ، وَمَا فِيهِ عِلَّةٌ قَادِحَةٌ، وَمَا فِي رَاوِيهِ نَوْعُ جَرْحٍ». والحكمُ بالصحّة حكمٌ على الظاهر بحسب اجتماع هذه الشروط، لا قطعٌ بثبوت الخبر في نفس الأمر، قال: «وَلَيْسَ مِنْ شَرْطِهِ أَنْ يَكُونَ مَقْطُوعًا بِهِ فِي نَفْسِ الْأَمْرِ، إِذْ مِنْهُ مَا يَنْفَرِدُ بِرِوَايَتِهِ عَدْلٌ وَاحِدٌ، وَلَيْسَ مِنَ الْأَخْبَارِ الَّتِي أَجْمَعَتِ الْأُمَّةُ عَلَى تَلَقِّيهَا بِالْقَبُولِ»؛ إلا ما أجمعت الأمة على تلقّيه بالقبول فإنه مقطوعٌ به عنده.',
  reference = 'مقدمة ابن الصلاح في علوم الحديث (معرفة أنواع علوم الحديث، ت نور الدين عتر، دار الفكر بسوريا ودار الفكر المعاصر ببيروت، ١٤٠٦هـ/١٩٨٦م): ص١١-١٢ (النوع الأول من أنواع علوم الحديث: معرفة الصحيح من الحديث)، وص١٣-١٤ (معنى قولهم في الحديث: هذا حديث صحيح) | الكلمات المفتاحية: الحديث الصحيح، مصطلح الحديث',
  evidence = 'قال ابن الصلاح في مقدمته: «اعْلَمْ - عَلَّمَكَ اللَّهُ وَإِيَّايَ - أَنَّ الْحَدِيثَ عِنْدَ أَهْلِهِ يَنْقَسِمُ إِلَى: صَحِيحٍ، وَحَسَنٍ، وَضَعِيفٍ. أَمَّا الْحَدِيثُ الصَّحِيحُ: فَهُوَ الْحَدِيثُ الْمُسْنَدُ الَّذِي يَتَّصِلُ إِسْنَادُهُ» (ص١١) «بِنَقْلِ الْعَدْلِ الضَّابِطِ عَنِ الْعَدْلِ الضَّابِطِ إِلَى مُنْتَهَاهُ، وَلَا يَكُونُ شَاذًّا، وَلَا مُعَلَّلًا. وَفِي هَذِهِ الْأَوْصَافِ احْتِرَازٌ عَنِ الْمُرْسَلِ، وَالْمُنْقَطِعِ، وَالْمُعْضَلِ، وَالشَّاذِّ، وَمَا فِيهِ عِلَّةٌ قَادِحَةٌ، وَمَا فِي رَاوِيهِ نَوْعُ جَرْحٍ» (ص١٢) — فقيدُ ‹القادحة› عنده في العلّة المحترَز عنها، ولفظُ حدِّه «وَلَا مُعَلَّلًا». ثم بيَّن أنّ الحكم بالصحّة ظاهريٌّ فقال: «وَمَتَى قَالُوا: " هَذَا حَدِيثٌ صَحِيحٌ " فَمَعْنَاهُ: أَنَّهُ اتَّصَلَ سَنَدُهُ مَعَ» (ص١٣) «سَائِرِ الْأَوْصَافِ الْمَذْكُورَةِ، وَلَيْسَ مِنْ شَرْطِهِ أَنْ يَكُونَ مَقْطُوعًا بِهِ فِي نَفْسِ الْأَمْرِ، إِذْ مِنْهُ مَا يَنْفَرِدُ بِرِوَايَتِهِ عَدْلٌ وَاحِدٌ، وَلَيْسَ مِنَ الْأَخْبَارِ الَّتِي أَجْمَعَتِ الْأُمَّةُ عَلَى تَلَقِّيهَا بِالْقَبُولِ» (ص١٤).',
  verification_status = 'verified'
WHERE id = '3c7c003b-3562-40da-86d8-c04ed2738124'
  AND reference = 'مقدمة ابن الصلاح في علوم الحديث | الكلمات المفتاحية: الحديث الصحيح، مصطلح الحديث'
  AND evidence = 'التعريف المشهور عند علماء مصطلح الحديث (كابن الصلاح في مقدمته).'
  AND answer = 'ما اتصل سنده بنقل العدل الضابط عن مثله إلى منتهاه، من غير شذوذ ولا علة قادحة.';
